-- One row per point: Id|SRID|STAsText|long bits|lat bits|Z bits|M bits (IEEE 754, big-endian hex).
SELECT Id, Loc.STSrid, Loc.STAsText(), CONVERT(varchar(16), CONVERT(binary(8), Loc.Long), 2), CONVERT(varchar(16), CONVERT(binary(8), Loc.Lat), 2), CONVERT(varchar(16), CONVERT(binary(8), Loc.Z), 2), CONVERT(varchar(16), CONVERT(binary(8), Loc.M), 2) FROM dbo.G WHERE Id <= 15 ORDER BY Id;
-- The shapes the converter leaves alone (SRID 4269, polygon, multipolygon), stored and read back.
SELECT Id, Loc.STSrid, Loc.STGeometryType(), Loc.STAsText() FROM dbo.G WHERE Id > 15 ORDER BY Id;
